def runde_auswerten(karte1, karte2, preiskarte, punkte1, punkte2):
    if karte1 > karte2:
        return punkte1 + preiskarte, punkte2
    elif karte2 > karte1:
        return punkte1, punkte2 + preiskarte
    else:
        return punkte1, punkte2

